// Arduino Uno R3: 10-bit ADC (0-1023) to 8-bit PWM (0-255)
const int POT_PIN = A0;
const int LED_PWM_PIN = 9; // ~PWM pin on Uno R3

void setup() {
  pinMode(LED_PWM_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int raw = analogRead(POT_PIN);         // 0..1023
  int brightness = map(raw, 0, 1023, 0, 255);
  analogWrite(LED_PWM_PIN, brightness);
  Serial.println(brightness);
  delay(50);
}

