// Arduino Uno R4: 12-bit ADC resolution example
const int SENSOR_PIN = A1;

void setup() {
  Serial.begin(115200);
  analogReadResolution(12); // 0..4095 on Uno R4
}

void loop() {
  int reading = analogRead(SENSOR_PIN);
  float volts = (reading * 5.0f) / 4095.0f;
  Serial.print("Voltage: ");
  Serial.println(volts, 3);
  delay(250);
}

