// Arduino Nano Classic: Reading analog-only pin A6
const int LIGHT_PIN = A6; // Analog-only on Nano Classic
const int STATUS_LED = 13;

void setup() {
  pinMode(STATUS_LED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int lightVal = analogRead(LIGHT_PIN);
  digitalWrite(STATUS_LED, lightVal < 400 ? HIGH : LOW);
  Serial.println(lightVal);
  delay(200);
}

