// Arduino Mega 2560: Using hardware Serial1 alongside USB Serial
void setup() {
  Serial.begin(9600);   // USB Monitor
  Serial1.begin(9600);  // Hardware UART on pins 18 (TX1) & 19 (RX1)
  Serial.println("Mega 2560 Multi-UART Ready");
}

void loop() {
  if (Serial1.available()) {
    char incoming = Serial1.read();
    Serial.print("From Serial1: ");
    Serial.println(incoming);
  }
}

