// ESP32-WROOM-32: 12-bit ADC on ADC1 pin (GPIO 34, input-only)
const int SENSOR_PIN = 34; // ADC1 channel (safe with Wi-Fi)
const int LED_PIN = 2;     // Onboard LED on many DevKit boards

void setup() {
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(115200);
}

void loop() {
  int raw = analogRead(SENSOR_PIN); // 0..4095 (3.3V max!)
  digitalWrite(LED_PIN, raw > 2048 ? HIGH : LOW);
  Serial.println(raw);
  delay(200);
}

